#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 1024

int main(int argc, char *argv[])
{
    const char *input;
    size_t in_len;
    char norm[MAX_INPUT_LEN + 1];
    size_t norm_len = 0;

    if (argc > 1) {
        input = argv[1];
    } else {
        input = "";
    }

    in_len = strlen(input);
    if (in_len > MAX_INPUT_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    for (size_t i = 0; i < in_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            if (isalpha(c))
                c = (unsigned char)tolower(c);
            norm[norm_len++] = (char)c;
        }
    }
    norm[norm_len] = '\0';

    int is_pal = 1;
    for (size_t i = 0; i < norm_len / 2; ++i) {
        if (norm[i] != norm[norm_len - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    if (is_pal)
        puts("PALINDROME");
    else
        puts("NOT_PALINDROME");

    return 0;
}
